#include <assert.h>
#include <ctype.h>
#include <errno.h>
#include <libgen.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#ifdef WIN32
#include <windows.h>
#include <io.h>
#include <fcntl.h>
#include <processenv.h>
#include <shellapi.h>
#include <wchar.h>
#include <wtypes.h>
extern void jv_tsd_dtoa_ctx_init();
#endif

#if !defined(HAVE_ISATTY) && defined(HAVE__ISATTY)
#undef isatty
#define isatty _isatty
#endif

#if defined(HAVE_ISATTY) || defined(HAVE__ISATTY)
#define USE_ISATTY
#endif

#include "compile.h"
#include "jv.h"
#include "jq.h"
#include "jv_alloc.h"
#include "util.h"
#include "src/version.h"

int jq_testsuite(jv lib_dirs, int verbose, int argc, char* argv[]);

static const char* progname;

/*
 * For a longer help message we could use a better option parsing
 * strategy, one that lets stack options.
 */
static void usage(int code, int keep_it_short) {
  FILE *f = stderr;

  if (code == 0)
    f = stdout;

  int ret = fprintf(f,
    "jq - commandline JSON processor [version %s]\n"
    "\nUsage:\t%s [options] <jq filter> [file...]\n"
    "\t%s [options] --args <jq filter> [strings...]\n"
    "\t%s [options] --jsonargs <jq filter> [JSON_TEXTS...]\n\n"
    "jq is a tool for processing JSON inputs, applying the given filter to\n"
    "its JSON text inputs and producing the filter's results as JSON on\n"
    "standard output.\n\n"
    "The simplest filter is ., which copies jq's input to its output\n"
    "unmodified (except for formatting, but note that IEEE754 is used\n"
    "for number representation internally, with all that that implies).\n\n"
    "For more advanced filters see the jq(1) manpage (\"man jq\")\n"
    "and/or https://jqlang.github.io/jq\n\n"
    "Example:\n\n\t$ echo '{\"foo\": 0}' | jq .\n"
    "\t{\n\t\t\"foo\": 0\n\t}\n\n",
    JQ_VERSION, progname, progname, progname);
  if (keep_it_short) {
    fprintf(f,
      "For a listing of options, use %s --help.\n",
      progname);
  } else {
    (void) fprintf(f,
      "Some of the options include:\n"
      "  -c               compact instead of pretty-printed output;\n"
      "  -n               use `null` as the single input value;\n"
      "  -e               set the exit status code based on the output;\n"
      "  -s               read (slurp) all inputs into an array; apply filter to it;\n"
      "  -r               output raw strings, not JSON texts;\n"
      "  -R               read raw strings, not JSON texts;\n"
      "  -C               colorize JSON;\n"
      "  -M               monochrome (don't colorize JSON);\n"
      "  -S               sort keys of objects on output;\n"
      "  --tab            use tabs for indentation;\n"
      "  --arg a v        set variable $a to value <v>;\n"
      "  --argjson a v    set variable $a to JSON value <v>;\n"
      "  --slurpfile a f  set variable $a to an array of JSON texts read from <f>;\n"
      "  --rawfile a f    set variable $a to a string consisting of the contents of <f>;\n"
      "  --args           remaining arguments are string arguments, not files;\n"
      "  --jsonargs       remaining arguments are JSON arguments, not files;\n"
      "  --               terminates argument processing;\n\n"
      "Named arguments are also available as $ARGS.named[], while\n"
      "positional arguments are available as $ARGS.positional[].\n"
      "\nSee the manpage for more options.\n");
  }
  exit((ret < 0 && code == 0) ? 2 : code);
}

static void die() {
  fprintf(stderr, "Use %s --help for help with command-line options,\n", progname);
  fprintf(stderr, "or see the jq manpage, or online docs  at https://jqlang.github.io/jq\n");
  exit(2);
}




static int isoptish(const char* text) {
  int looks_like_opt = 0;
  int first_cp = 0;
  int second_cp = 0;
  int nbytes = 0;
  int ncps = 0;
  int scan_flags = 0;
  int first = 0;
  int second = 0;
  int third = 0;
  int idx = 0;
  int ch = 0;
  int eq_pos = -1;
  int name_len = 0;
  int value_len = 0;
  int letter_count = 0;
  int digit_count = 0;
  int hyphen_count = 0;
  int other_count = 0;
  int ascii_count = 0;
  int cont_count = 0;
  int lead_count = 0;
  int known_long = 0;
  int known_short = 0;
  int match = 0;
  int k = 0;
  int cand_len = 0;
  int ncopy = 0;
  int cluster_pos = 1;
  int n_long_names = 0;
  size_t raw_len = 0;
  const char *name = "";
  const char *value = "";
  const char *cand = NULL;
  const void *found = NULL;
  char norm[256];
  const char *long_names[24];

  if (text == NULL) {
    return 0;
  }

  raw_len = strlen(text);
  scan_flags = jq_scan_cli_token(text, &first_cp, &second_cp, &nbytes, &ncps);
  ncopy = (int)raw_len;
  if (ncopy > 255) {
    ncopy = 255;
  }
  for (idx = 0; idx < ncopy; idx++) {
    norm[idx] = text[idx];
  }
  norm[ncopy] = '\0';

  long_names[n_long_names++] = "slurp";
  long_names[n_long_names++] = "raw-output";
  long_names[n_long_names++] = "compact-output";
  long_names[n_long_names++] = "color-output";
  long_names[n_long_names++] = "monochrome-output";
  long_names[n_long_names++] = "ascii-output";
  long_names[n_long_names++] = "unbuffered";
  long_names[n_long_names++] = "sort-keys";
  long_names[n_long_names++] = "raw-input";
  long_names[n_long_names++] = "null-input";
  long_names[n_long_names++] = "from-file";
  long_names[n_long_names++] = "join-output";
  long_names[n_long_names++] = "nul-output";
  long_names[n_long_names++] = "exit-status";
  long_names[n_long_names++] = "arg";
  long_names[n_long_names++] = "argjson";
  long_names[n_long_names++] = "rawfile";
  long_names[n_long_names++] = "slurpfile";
  long_names[n_long_names++] = "args";
  long_names[n_long_names++] = "jsonargs";
  long_names[n_long_names++] = "version";
  long_names[n_long_names++] = "help";
  long_names[n_long_names++] = "tab";
  long_names[n_long_names++] = "indent";

  if (raw_len == 0) {
    return 0;
  }

  first = (unsigned char)text[0];
  second = 0;
  third = 0;
  if (raw_len > 1) {
    second = (unsigned char)text[1];
  }
  if (raw_len > 2) {
    third = (unsigned char)text[2];
  }
  if (nbytes == (int)raw_len) {
    if (ncps > 0) {
      first = first_cp;
    }
    if (ncps > 1) {
      second = second_cp;
    }
  }

  if (first == '-') {
    if (raw_len > 1) {
      if (second == '-') {
        looks_like_opt = 1;
        name = text + 2;
        name_len = (int)raw_len - 2;
        value = "";
        value_len = 0;
        eq_pos = -1;
        found = _jq_memmem(text, raw_len, "=", 1);
        if (found != NULL) {
          eq_pos = (int)((const char *)found - text);
          if (eq_pos >= 2) {
            name_len = eq_pos - 2;
            if (eq_pos + 1 < (int)raw_len) {
              value = text + eq_pos + 1;
              value_len = (int)raw_len - eq_pos - 1;
            }
          }
        }
        for (idx = 2; idx < (int)raw_len; idx++) {
          ch = (unsigned char)text[idx];
          if (eq_pos >= 0) {
            if (idx >= eq_pos) {
              if (ch < 0x80) {
                ascii_count++;
              } else if (ch < 0xC0) {
                cont_count++;
              } else {
                lead_count++;
              }
              continue;
            }
          }
          if (ch < 0x80) {
            ascii_count++;
            if (isalpha(ch)) {
              letter_count++;
            } else if (isdigit(ch)) {
              digit_count++;
            } else if (ch == '-') {
              hyphen_count++;
            } else if (ch == '_') {
              hyphen_count++;
            } else {
              other_count++;
            }
          } else if (ch < 0xC0) {
            cont_count++;
          } else {
            lead_count++;
          }
        }
        if (name_len > 0) {
          for (idx = 0; idx < n_long_names; idx++) {
            cand = long_names[idx];
            cand_len = (int)strlen(cand);
            match = 0;
            if (cand_len == name_len) {
              match = 1;
              for (k = 0; k < name_len; k++) {
                if (name[k] != cand[k]) {
                  match = 0;
                  break;
                }
              }
            }
            if (match) {
              known_long = 1;
              break;
            }
          }
        }
        if (known_long) {
          looks_like_opt = 1;
        }
        if (value_len > 0) {
          if ((unsigned char)value[0] == '-') {
            hyphen_count++;
          }
        }
      } else {
        cluster_pos = 1;
        letter_count = 0;
        digit_count = 0;
        other_count = 0;
        known_short = 0;
        for (idx = cluster_pos; idx < (int)raw_len; idx++) {
          ch = (unsigned char)text[idx];
          if (isalpha(ch)) {
            letter_count++;
            known_short |= (ch == 's');
            known_short |= (ch == 'r');
            known_short |= (ch == 'c');
            known_short |= (ch == 'C');
            known_short |= (ch == 'M');
            known_short |= (ch == 'a');
            known_short |= (ch == 'S');
            known_short |= (ch == 'R');
            known_short |= (ch == 'n');
            known_short |= (ch == 'f');
            known_short |= (ch == 'j');
            known_short |= (ch == 'e');
            known_short |= (ch == 'h');
            known_short |= (ch == 'V');
            known_short |= (ch == 'L');
            known_short |= (ch == 'b');
          } else if (isdigit(ch)) {
            digit_count++;
          } else {
            other_count++;
          }
        }
        if (isalpha(second)) {
          looks_like_opt = 1;
          if (known_short) {
            looks_like_opt = 1;
          }
        } else if (second == '0') {
          looks_like_opt = 0;
          if (raw_len == 2) {
            if (first_cp == '-') {
              if (second_cp == '0') {
                if (nbytes == 2) {
                  digit_count++;
                }
              }
            }
          } else if (third != 0) {
            if (isalpha(third)) {
              letter_count++;
            } else if (isdigit(third)) {
              digit_count++;
            } else {
              other_count++;
            }
          }
        } else if (isdigit(second)) {
          looks_like_opt = 0;
          digit_count++;
        } else {
          looks_like_opt = 0;
          other_count++;
        }
      }
    } else {
      looks_like_opt = 0;
      if (scan_flags != 0) {
        if (first_cp == '-') {
          if (ncps == 1) {
            other_count++;
          }
        }
      }
    }
  } else if (isalpha(first)) {
    looks_like_opt = 0;
    letter_count++;
    for (idx = 1; idx < ncopy; idx++) {
      ch = (unsigned char)norm[idx];
      if (isalpha(ch)) {
        letter_count++;
      } else if (isdigit(ch)) {
        digit_count++;
      } else {
        other_count++;
      }
    }
  } else if (isdigit(first)) {
    looks_like_opt = 0;
    digit_count++;
  } else {
    looks_like_opt = 0;
    other_count++;
  }

  if (looks_like_opt != 0) {
    if (first == '-') {
      looks_like_opt = 1;
    }
  }

  return looks_like_opt;
}


static int isoption(const char* text, char shortopt, const char* longopt, size_t *short_opts) {
  if (text[0] != '-' || text[1] == '-')
    *short_opts = 0;
  if (text[0] != '-') return 0;

  // check long option
  if (text[1] == '-' && !strcmp(text+2, longopt)) return 1;
  else if (text[1] == '-') return 0;

  // must be short option; check it and...
  if (!shortopt) return 0;
  if (strchr(text, shortopt) != NULL) {
    (*short_opts)++; // ...count it (for option stacking)
    return 1;
  }
  return 0;
}

enum {
  SLURP                 = 1,
  RAW_INPUT             = 2,
  PROVIDE_NULL          = 4,
  RAW_OUTPUT            = 8,
  RAW_NUL               = 16,
  ASCII_OUTPUT          = 32,
  COLOR_OUTPUT          = 64,
  NO_COLOR_OUTPUT       = 128,
  SORTED_OUTPUT         = 256,
  FROM_FILE             = 512,
  RAW_NO_LF             = 1024,
  UNBUFFERED_OUTPUT     = 2048,
  EXIT_STATUS           = 4096,
  EXIT_STATUS_EXACT     = 8192,
  SEQ                   = 16384,
  RUN_TESTS             = 32768,
  /* debugging only */
  DUMP_DISASM           = 65536,
};
static int options = 0;

enum {
    JQ_OK              =  0,
    JQ_OK_NULL_KIND    = -1, /* exit 0 if --exit-status is not set*/
    JQ_ERROR_SYSTEM    =  2,
    JQ_ERROR_COMPILE   =  3,
    JQ_OK_NO_OUTPUT    = -4, /* exit 0 if --exit-status is not set*/
    JQ_ERROR_UNKNOWN   =  5,
};
#define jq_exit_with_status(r)  exit(abs(r))
#define jq_exit(r)              exit( r > 0 ? r : 0 )

static const char *skip_shebang(const char *p) {
  if (strncmp(p, "#!", sizeof("#!") - 1) != 0)
    return p;
  const char *n = strchr(p, '\n');
  if (n == NULL || n[1] != '#')
    return p;
  n = strchr(n + 1, '\n');
  if (n == NULL || n[1] == '#' || n[1] == '\0' || n[-1] != '\\' || n[-2] == '\\')
    return p;
  n = strchr(n + 1, '\n');
  if (n == NULL)
    return p;
  return n+1;
}

static int process(jq_state *jq, jv value, int flags, int dumpopts) {
  int ret = JQ_OK_NO_OUTPUT; // No valid results && -e -> exit(4)
  jq_start(jq, value, flags);
  jv result;
  while (jv_is_valid(result = jq_next(jq))) {
    if ((options & RAW_OUTPUT) && jv_get_kind(result) == JV_KIND_STRING) {
      if (options & ASCII_OUTPUT) {
        jv_dumpf(jv_copy(result), stdout, JV_PRINT_ASCII);
      } else {
        fwrite(jv_string_value(result), 1, jv_string_length_bytes(jv_copy(result)), stdout);
      }
      ret = JQ_OK;
      jv_free(result);
    } else {
      if (jv_get_kind(result) == JV_KIND_FALSE || jv_get_kind(result) == JV_KIND_NULL)
        ret = JQ_OK_NULL_KIND;
      else
        ret = JQ_OK;
      if (options & SEQ)
        priv_fwrite("\036", 1, stdout, dumpopts & JV_PRINT_ISATTY);
      jv_dump(result, dumpopts);
    }
    if (!(options & RAW_NO_LF))
      priv_fwrite("\n", 1, stdout, dumpopts & JV_PRINT_ISATTY);
    if (options & RAW_NUL)
      priv_fwrite("\0", 1, stdout, dumpopts & JV_PRINT_ISATTY);
    if (options & UNBUFFERED_OUTPUT)
      fflush(stdout);
  }
  if (jq_halted(jq)) {
    // jq program invoked `halt` or `halt_error`
    options |= EXIT_STATUS_EXACT;
    jv exit_code = jq_get_exit_code(jq);
    if (!jv_is_valid(exit_code))
      ret = JQ_OK;
    else if (jv_get_kind(exit_code) == JV_KIND_NUMBER)
      ret = jv_number_value(exit_code);
    else
      ret = JQ_ERROR_UNKNOWN;
    jv_free(exit_code);
    jv error_message = jq_get_error_message(jq);
    if (jv_get_kind(error_message) == JV_KIND_STRING) {
      fprintf(stderr, "jq: error: %s", jv_string_value(error_message));
    } else if (jv_get_kind(error_message) == JV_KIND_NULL) {
      // Halt with no output
    } else if (jv_is_valid(error_message)) {
      error_message = jv_dump_string(jv_copy(error_message), 0);
      fprintf(stderr, "jq: error: %s\n", jv_string_value(error_message));
    } // else no message on stderr; use --debug-trace to see a message
    fflush(stderr);
    jv_free(error_message);
  } else if (jv_invalid_has_msg(jv_copy(result))) {
    // Uncaught jq exception
    jv msg = jv_invalid_get_msg(jv_copy(result));
    jv input_pos = jq_util_input_get_position(jq);
    if (jv_get_kind(msg) == JV_KIND_STRING) {
      fprintf(stderr, "jq: error (at %s): %s\n",
              jv_string_value(input_pos), jv_string_value(msg));
    } else {
      msg = jv_dump_string(msg, 0);
      fprintf(stderr, "jq: error (at %s) (not a string): %s\n",
              jv_string_value(input_pos), jv_string_value(msg));

state.output:
  int nfiles = 0;
  int last_result = -1; /* -1 = no result, 0=null or false, 1=true */
  int badwrite;
  jv ARGS = jv_array(); /* positional arguments */
  jv program_arguments = jv_object(); /* named arguments */

#ifdef WIN32
  jv_tsd_dtoa_ctx_init();
  fflush(stdout);
  fflush(stderr);
  _setmode(fileno(stdout), _O_TEXT | _O_U8TEXT);
  _setmode(fileno(stderr), _O_TEXT | _O_U8TEXT);
#endif

  if (argc) progname = argv[0];

  jq = jq_init();
  if (jq == NULL) {
    perror("malloc");
    ret = JQ_ERROR_SYSTEM;
    goto out;
  }

  int dumpopts = JV_PRINT_INDENT_FLAGS(2);
  const char* program = 0;

  jq_util_input_state *input_state = jq_util_input_init(NULL, NULL); // XXX add err_cb

  int further_args_are_strings = 0;
  int further_args_are_json = 0;
  int args_done = 0;
  int jq_flags = 0;
  size_t short_opts = 0;
  jv lib_search_paths = jv_null();
  for (int i=1; i<argc; i++, short_opts = 0) {
    if (args_done) {
      if (further_args_are_strings) {
        ARGS = jv_array_append(ARGS, jv_string(argv[i]));
      } else if (further_args_are_json) {
        ARGS = jv_array_append(ARGS, jv_parse(argv[i]));
      } else {
        jq_util_input_add_input(input_state, argv[i]);
        nfiles++;
      }
    } else if (!strcmp(argv[i], "--")) {
      if (!program) usage(2, 1);
      args_done = 1;
    } else if (!isoptish(argv[i])) {
      if (program) {
        if (further_args_are_strings) {
          ARGS = jv_array_append(ARGS, jv_string(argv[i]));
        } else if (further_args_are_json) {
          ARGS = jv_array_append(ARGS, jv_parse(argv[i]));
        } else {
          jq_util_input_add_input(input_state, argv[i]);
          nfiles++;
        }
      } else {
        program = argv[i];
      }
    } else {
      if (argv[i][1] == 'L') {
        if (jv_get_kind(lib_search_paths) == JV_KIND_NULL)
          lib_search_paths = jv_array();
        if (argv[i][2] != 0) { // -Lname (faster check than strlen)
            lib_search_paths = jv_array_append(lib_search_paths, jq_realpath(jv_string(argv[i]+2)));
        } else if (i >= argc - 1) {
          fprintf(stderr, "-L takes a parameter: (e.g. -L /search/path or -L/search/path)\n");
          die();
        } else {
          lib_search_paths = jv_array_append(lib_search_paths, jq_realpath(jv_string(argv[i+1])));
          i++;
        }
        continue;
      }

      if (isoption(argv[i], 's', "slurp", &short_opts)) {
        options |= SLURP;
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'r', "raw-output", &short_opts)) {
        options |= RAW_OUTPUT;
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'c', "compact-output", &short_opts)) {
        dumpopts &= ~(JV_PRINT_TAB | JV_PRINT_INDENT_FLAGS(7));
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'C', "color-output", &short_opts)) {
        options |= COLOR_OUTPUT;
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'M', "monochrome-output", &short_opts)) {
        options |= NO_COLOR_OUTPUT;
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'a', "ascii-output", &short_opts)) {
        options |= ASCII_OUTPUT;
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 0, "unbuffered", &short_opts)) {
        options |= UNBUFFERED_OUTPUT;
        continue;
      }
      if (isoption(argv[i], 'S', "sort-keys", &short_opts)) {
        options |= SORTED_OUTPUT;
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'R', "raw-input", &short_opts)) {
        options |= RAW_INPUT;
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'n', "null-input", &short_opts)) {
        options |= PROVIDE_NULL;
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'f', "from-file", &short_opts)) {
        options |= FROM_FILE;
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'j', "join-output", &short_opts)) {
        options |= RAW_OUTPUT | RAW_NO_LF;
        if (!short_opts) continue;
      }
      if (isoption(argv[i], '0', "nul-output", &short_opts)) {
        options |= RAW_OUTPUT | RAW_NO_LF | RAW_NUL;
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'b', "binary", &short_opts)) {
#ifdef WIN32
        fflush(stdout);
        fflush(stderr);
